// Report record page (moderators): context + actions.
import React, { useCallback, useEffect, useState } from 'react';
import { Text, View } from 'react-native';
import { router, Stack, useLocalSearchParams } from 'expo-router';
import { Button, EmptyState, ErrorText, FieldGrid, HighlightPanel, ListRow, ListView, Page, PersonFace, SectionCard, StatusPill, styles } from '../../components/ui';
import { NotFound, loadReports, useCanModerate, type ReportCtx } from '../../components/mod';
import { resolveReport, setBan, softDeleteMessage } from '../../lib/api';
import { fmtDate } from '../../lib/format';
import { fullName, handle } from '../../lib/names';
import { fs } from '../../lib/theme';

export default function ReportPage() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const { ready, ok, userId } = useCanModerate();
  const [x, setX] = useState<ReportCtx | null | undefined>(undefined);
  const [err, setErr] = useState<string | null>(null);
  const [note, setNote] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);
  const load = useCallback(() => loadReports().then((all) => setX(all.find((r) => String(r.report.id) === id) ?? null)).catch((e) => setErr(e.message)), [id]);
  useEffect(() => { if (ok) load(); }, [ok, load]);
  if (!ready) return <View style={{ flex: 1 }} />;
  if (!ok || !userId) return <NotFound />;

  const act = async (label: string, fn: () => Promise<void>, leave = false) => {
    setBusy(true); setErr(null);
    try { await fn(); setNote(label); if (leave) router.back(); else await load(); } catch (e: any) { setErr(e.message); } finally { setBusy(false); }
  };
  const person = (pid: string | null) => (pid && x ? x.people[pid] : undefined);
  const m = x?.message;
  return (
    <Page>
      <Stack.Screen options={{ title: 'Report' }} />
      <ErrorText>{err}</ErrorText>
      {note ? <Text style={[styles.muted, { fontSize: fs(13) }]}>{note}</Text> : null}
      {x === null ? <EmptyState icon="checkmark-done-outline" title="Report closed" body="This report is no longer open." action={<Button small variant="neutral" title="Back to reports" onPress={() => router.replace('/reports')} />} /> : null}
      {x ? <>
        <HighlightPanel icon="flag" eyebrow={`Report #${x.report.id}`} title={x.report.reason || '(no reason given)'} subtitle={fmtDate(x.report.created_at)}
          pills={<><StatusPill label={x.report.status} tone="warning" /><StatusPill label={m ? 'Message' : 'Member'} tone="info" /></>}
          actions={<>
            <Button small title="Resolve" loading={busy} onPress={() => act('Resolved.', () => resolveReport(x.report.id, 'actioned', userId), true)} />
            <Button small variant="neutral" title="Dismiss" onPress={() => act('Dismissed.', () => resolveReport(x.report.id, 'dismissed', userId), true)} />
          </>}
          fields={[['Reported by', fullName(person(x.report.reporter_id))], ['About', x.target ? fullName(person(x.target)) : '—']]} />
        {m ? (
          <SectionCard title="Reported message" actions={!m.deleted_at ? <Button small variant="destructive" icon="trash-outline" title="Remove message"
            onPress={() => act('Message removed.', () => softDeleteMessage(m.id))} /> : <StatusPill label="Removed" tone="danger" />}>
            <Text style={[styles.body, { fontStyle: 'italic' }]}>“{m.body}”</Text>
            <View style={{ marginTop: 12 }}>
              <FieldGrid fields={[['Sent', fmtDate(m.created_at)], ['Chat', <Text style={styles.link} onPress={() => router.push(`/rooms/${m.room_id}`)}>Open chat</Text>]]} />
            </View>
          </SectionCard>) : null}
        <ListView title="People">
          {[['Reported member', x.target], ['Reporter', x.report.reporter_id]].filter(([, pid]) => pid).map(([label, pid]) => (
            <ListRow key={label as string} onPress={() => router.push(`/profile?id=${pid}`)}>
              <PersonFace fill size={30} name={fullName(person(pid as string))} subtitle={`${label} · ${handle(person(pid as string))}`}
                path={person(pid as string)?.avatar_path} userId={pid as string} />
            </ListRow>))}
        </ListView>
        {x.target ? (
          <SectionCard title="Enforcement">
            <View style={{ flexDirection: 'row', gap: 8, alignItems: 'center', flexWrap: 'wrap' }}>
              <Button small variant="destructive" icon="ban-outline" title={`Ban ${fullName(person(x.target))}`} onPress={() => act('Member banned.', () => setBan(x.target!, true))} />
              <Text style={[styles.muted, { fontSize: fs(13) }]}>Bans block posting app-wide. Undo from their profile.</Text>
            </View>
          </SectionCard>) : null}
      </> : null}
    </Page>
  );
}
